import source from '@/data/source-scans.json';

export const scanOutcomes = [
  'evidence_observed',
  'alternative_observed',
  'evidence_not_reobserved',
  'no_mention',
  'compatibility_only',
  'generic_foldable',
  'bug_fix_only',
  'unspecified_improvement',
  'preparing',
] as const;
export type ScanOutcome = (typeof scanOutcomes)[number];
export type SourceScan = {
  checkedAt: string;
  versions: number;
  outcome: ScanOutcome;
  excerpt?: string;
  excerptVersion?: string | null;
};
// Generated by scripts/build-source-scans.ts from the latest verified refresh.
// A summary of what official KR sources showed; it never changes a support decision.
export const sourceScans = source as {
  version: number;
  refresh: string;
  country: 'KR';
  apps: Record<string, SourceScan>;
};
export function scanForApp(storeUrl: string) {
  const id = /^https:\/\/apps\.apple\.com\/kr\/app\/(?:[^/]+\/)?id([0-9]+)$/.exec(storeUrl)?.[1];
  return id && Object.hasOwn(sourceScans.apps, id) ? sourceScans.apps[id] : null;
}
